// Foto menu, logo, dan QRIS tertanam langsung (data URI) supaya tetap tampil walau file gambar tidak satu folder / beda nama.
// File ini dibuat otomatis. Kalau mau ganti foto, ganti/hapus entri di sini atau pakai nama file di data.js.
const FOTO_DATA={
  0:'data:image/jpeg;base64,',
  1:'data:image/jpeg;base64,',
  2:'data:image/jpeg;base64,',
  3:'data:image/jpeg;base64,',
  4:'data:image/jpeg;base64,',
  5:'data:image/jpeg;base64,',
  6:'data:image/jpeg;base64,',
  7:'data:image/jpeg;base64,',
  8:'data:image/jpeg;base64,',
  9:'data:image/jpeg;base64,',
};
const LOGO_DATA='data:image/jpeg;base64,';
const QRIS_DATA='data:image/jpeg;base64,';

// pasang ke data.js / halaman
Object.keys(FOTO_DATA).forEach(k=>{FOTO_MENU[k]=FOTO_DATA[k]});
BG_FOTO.length=0;Object.values(FOTO_DATA).forEach(f=>BG_FOTO.push(f));
document.querySelectorAll('.brand img, .hero-logo').forEach(i=>i.src=LOGO_DATA);
document.querySelectorAll('img[src^="qris"]').forEach(i=>i.src=QRIS_DATA);
document.querySelector('link[rel=icon]').href=LOGO_DATA;